"""Data behind .bookkeeping/data_flow.md and data_flow.svg (the data-flow record).

Edit this file when a store table, writer, source, key, write rule or retention changes, then run
``python .bookkeeping/tools/render_flow.py`` from the repo root and commit the regenerated files.

Every value carries its source:
- ``path:line`` is a file in this repo at the commit named in ``AS_OF``;
- ``:NNNN`` alone is a line of the MANIFEST in core/rawstore.py; ``uw.py`` is core/providers/unusual_whales.py;
- ``R2:n``, ``C2:n``, ``O2:n`` are rows of the phase 2 lineage study (verified against the same commit);
- "store write scan" means a search of every rawstore write call outside tests found no other writer.
"""

# Prose, and no trailing full stop: render_flow.py puts its own punctuation after this, both in
# the markdown line and in the HTML page's subtitle.
AS_OF = (
    "Carried over from the private repo alsanvolkan/RevenueChaser at main f2d74a1c (2026-10-21), "
    "whose history this repo does not share: the 2026-10-22 migration re-rooted the public repo. "
    "The dataset rows, writers, sources, keys, write rules and retention below are the private "
    "repo's last reviewed record and were not re-read against this repo. The 173 path:line cites "
    "are therefore unverified here: the files mostly carry the same names, but the line numbers "
    "point into commits this repo has no copy of, and two cited files moved "
    "(core/ohlc_cache.py -> module_swing_potential/ohlc_cache.py, module_spx_gamma/cftc.py -> "
    "core/providers/cftc.py). Re-reading every cite against this repo is its own pass; until it "
    "runs, treat a line number here as a hint and the code as the source of truth"
)

MODES = {
    "upsert": "one row per key; a new fetch overwrites that row",
    "replace per": "all rows of the group are deleted, then the new rows written",
    "replace all": "the whole table is deleted and rewritten in one transaction; an empty batch is refused unless the caller passes allow_empty=True (core/rawstore.py:2900-2937)",
    "append": "rows are added; nothing removes them",
    "file": "a JSON file in a folder per date",
}

